head.script:
	scwin.onpageload = function() {
		// 페이지 로드 시 초기화
		// 산출물관리 조회
		scwin.btn_search_onclick();
	};

	/************************** 조회 관련 함수 *************************/

	/**
	 * 조회 조건 초기화
	 */
	scwin.btn_reset_onclick = function(e) {
		// 조회 조건 초기화 (페이징 정보는 유지)
		var currentPageSize = dmp_outVo.get("pageSize");
		dmp_outVo.setEmptyValue();
		dmp_outVo.set("pageIndex", "1");
		dmp_outVo.set("pageSize", currentPageSize);

		console.log("조회 조건이 초기화되었습니다.");
	};

	/**
	 * 조회 버튼 클릭 이벤트
	 */		   
	scwin.btn_search_onclick = function(e) {
		// 페이지 번호 초기화 (첫 페이지로)
		dmp_outVo.set("pageIndex", "1");
		pgl_outList.setSelectedIndex(1);

		console.log("=== 산출물관리 조회 시작 ===");
		console.log("조회 조건:", dmp_outVo.getJSON());

		// 서버통신 - 산출물관리 조회
		$c.sbm.execute($p, sbm_selectOutVoList);
	};

	scwin.sbm_outList_submitdone = function(e) {
		console.log("=== 산출물관리 조회 응답 처리 ===");
		console.log("응답 데이터:", e.responseJSON);

		// error 수신시
		var elData = e.responseJSON.elData;
		var elHeader = e.responseJSON.elHeader;
		if(elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}

		// 총 레코드 수 업데이트
        spn_listCnt.setLabel(elData.totalCount);

        // 데이터를 그리드에 셋팅
        dlt_outVoList.setJSON(elData.outVoList);

        // 페이지 네비게이터 업데이트
        var totalPageCount = Math.ceil(elData.totalCount / dmp_outVo.get("pageSize"));
        pgl_outList.setCount(totalPageCount);

		// 페이징 정보 업데이트
        spn_totalPageCount.setValue(totalPageCount);
        spn_pageIndex.setValue(dmp_outVo.get("pageIndex"));
        pgl_outList.setSelectedIndex(dmp_outVo.get("pageIndex"));

        console.log("조회 완료 - 총 " + elData.totalCount + "건, " + totalPageCount + "페이지");
	};	

	/**
	 * 페이지 번호 클릭 이벤트
	 */
	scwin.pgl_outList_onclick = function(idx) {
		console.log("페이지 클릭:", idx);

		// 페이지 번호 세팅
		dmp_outVo.set("pageIndex", idx);

		// 서버통신 - 산출물관리 조회
		$c.sbm.execute($p, sbm_selectOutVoList);
	};

	/************************** 그리드 이벤트 *************************/

	/**
	 * 그리드 더블클릭 이벤트 - 팝업으로 상세 정보 표시
	 */
	scwin.grd_list_oncelldblclick = function(row, col, colId) {
		var selectedData = dlt_outVoList.getRowJSON(row);
		dmp_outVoDetail.setJSON(selectedData);

		pop_overlay.show();

		// 조회 모드로 설정
		scwin.setFormMode("view");

		setTimeout(function() {
			try {
				spn_popupTitle.setValue("산출물 상세정보");
			} catch(e) {
				setTimeout(function() {
					spn_popupTitle.setValue("산출물 상세정보");
				}, 50);
			}
		}, 50);

		// 파일 목록 로드
		scwin.loadFileList();
	};

	/************************** 팝업 관련 이벤트 *************************/

	/**
	 * 등록 버튼 클릭 (새 산출물 등록)
	 */
	scwin.reg_btn_onclick = function(e) {
		dmp_outVoDetail.setEmptyValue();

		// 기본값 설정
		dmp_outVoDetail.set("pjtId", "6");
		dmp_outVoDetail.set("pjtName", "ERP 시스템 고도화 프로젝트");
		dmp_outVoDetail.set("outputType", "DOC");

		// 파일 관련 초기화
		dlt_upload.setJSON([]);
		dlt_attVoList.setJSON([]);

		pop_overlay.show();

		// 등록 모드로 설정
		scwin.setFormMode("new");

		setTimeout(function() {
			try {
				spn_popupTitle.setValue("산출물 등록");
			} catch(e) {
				setTimeout(function() {
					spn_popupTitle.setValue("산출물 등록");
				}, 50);
			}
		}, 50);

		// 미리보기 초기화
		scwin.hideAllPreviewPanels();
		scwin.showNoPreview();
	};

	/**
	 * 팝업 닫기
	 */
	scwin.detail_esc_btn_onclick = function(e) {
		pop_overlay.hide();
	};

	/**
	 * 팝업 수정 버튼 클릭 이벤트
	 */
	scwin.btn_popup_edit_onclick = function(e) {
		// 수정 모드로 전환
		scwin.setFormMode("edit");
	};

	/**
	 * 폼 모드 설정 함수
	 */
	scwin.setFormMode = function(mode) {
		console.log("폼 모드 전환:", mode);

		if (mode === "edit") {
			// 수정 모드
			scwin.setFieldsReadOnly(false);
			scwin.setEditorMode(true);
			scwin.showFileUploadSection(true);

			// 버튼 상태 변경
			btn_save.show();
			btn_popup_edit.hide();
			btn_popup_delete.show();

		} else if (mode === "view") {
			// 조회 모드
			scwin.setFieldsReadOnly(true);
			scwin.setEditorMode(false);
			scwin.showFileUploadSection(false);

			// 버튼 상태 변경
			btn_save.hide();
			btn_popup_edit.show();
			btn_popup_delete.show();
		} else if (mode === "new") {
			// 등록 모드
			scwin.setFieldsReadOnly(false);
			scwin.setEditorMode(true);
			scwin.showFileUploadSection(true);

			// 버튼 상태 변경
			btn_save.show();
			btn_popup_edit.hide();
			btn_popup_delete.hide();
		}
	};

	/**
	 * 필드 읽기 전용 설정 함수
	 */
	scwin.setFieldsReadOnly = function(readOnly) {
		try {
			// 편집 가능한 필드들
			var editableFields = [
				"inp_outputName",     // 산출물명
				"sel_outputType"      // 산출물 유형
			];

			editableFields.forEach(function(fieldId) {
				var field = $p.getComponentById(fieldId);
				if (field && field.setReadOnly) {
					field.setReadOnly(readOnly);
				}
			});

			// 프로젝트명은 항상 readOnly
			var alwaysReadOnlyFields = ["inp_projectName"];
			alwaysReadOnlyFields.forEach(function(fieldId) {
				var field = $p.getComponentById(fieldId);
				if (field && field.setReadOnly) {
					field.setReadOnly(true);
				}
			});

		} catch(e) {
			console.error("필드 읽기 전용 설정 오류:", e);
		}
	};

	/**
	 * 에디터 모드 전환 함수
	 */
	scwin.setEditorMode = function(isEditMode) {
		console.log("에디터 모드 전환:", isEditMode ? "편집" : "조회");

		if (isEditMode) {
			// 편집 모드: 에디터 표시, 읽기 전용 숨김
			grp_description_edit.show();
			grp_description_view.hide();
		} else {
			// 조회 모드: 읽기 전용 표시, 에디터 숨김
			grp_description_edit.hide();
			grp_description_view.show();

			// HTML 내용을 텍스트로 변환하여 표시
			scwin.updateViewContent();
		}
	};

	/**
	 * 조회 모드에서 HTML 내용을 텍스트로 변환
	 */
	scwin.updateViewContent = function() {
		try {
			var description = dmp_outVoDetail.get("description") || "";

			// HTML 태그 제거하고 텍스트만 추출
			var descriptionText = scwin.stripHtmlTags(description);

			// 조회 영역에 설정
			txt_description_view.setValue(descriptionText);

		} catch(e) {
			console.error("내용 업데이트 실패:", e);
		}
	};

	/**
	 * HTML 태그 제거 함수
	 */
	scwin.stripHtmlTags = function(htmlString) {
		if (!htmlString) return "";

		// HTML 태그 제거
		var text = htmlString.replace(/<[^>]*>/g, "");

		// HTML 엔티티 디코딩
		text = text.replace(/&nbsp;/g, " ");
		text = text.replace(/&lt;/g, "<");
		text = text.replace(/&gt;/g, ">");
		text = text.replace(/&amp;/g, "&");
		text = text.replace(/&quot;/g, '"');

		// 여러 개의 공백이나 줄바꿈을 하나로 정리
		text = text.replace(/\s+/g, " ").trim();

		return text;
	};

	/************************** CRUD 트랜잭션 이벤트 *************************/

	/**
	 * 저장 버튼 클릭 이벤트
	 */	
	scwin.btn_save_onclick = function(e) {
		var outputName = dmp_outVoDetail.get("name");
		if (!outputName || outputName.trim() === "") {
			$c.win.alert("산출물명을 입력해주세요.");
			return;
		}

		var outputId = dmp_outVoDetail.get("id");

		if (outputId && outputId.trim() !== "") {
			// 수정 모드
			scwin.sendOutputAndFilesForUpdate();
		} else {
			// 등록 모드
			scwin.sendOutputAndFiles();
		}
	};

	/**
	 * 산출물과 파일 전송 (등록)
	 */
	scwin.sendOutputAndFiles = function() {
		console.log("sendOutputAndFiles() 시작됨");

		var formData = new FormData();

		formData.append("pjtId", dmp_outVoDetail.get("pjtId"));
		formData.append("name", dmp_outVoDetail.get("name"));
		formData.append("description", dmp_outVoDetail.get("description") || "");
		formData.append("outputType", dmp_outVoDetail.get("outputType") || "DOC");

		// 파일 추가
		if (mpd_html5Type && mpd_html5Type.fileArray) {
			var fileList = mpd_html5Type.fileArray;
			console.log("fileList", fileList);

			if (fileList && fileList.length > 0) {
				for (var i = 0; i < fileList.length; i++) {
					var realFile = fileList[i].file;
					console.log('real', realFile);
					formData.append("files", realFile);
				}
			}
		}

		fetch("/InsWebApp/OUT001InsWithFiles.pwkjson", {
			method: "POST",
			body: formData
		})
		.then(function(res) { return res.json(); })
		.then(function(res) {
			var elHeader = res.elHeader;
			if (!elHeader || elHeader.resSuc == false) {
				$c.win.alert(`에러: ${elHeader ? elHeader.resMsg : "알 수 없는 오류"}`);
				return;
			}

			$c.win.alert("등록되었습니다.");
			dlt_upload.removeAll();
			if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
				mpd_html5Type.removeAllFiles();
			}
			pop_overlay.hide();
			scwin.btn_search_onclick();
		})
		.catch(function(err) {
			console.error("전송 실패", err);
			$c.win.alert("트랜잭션 실패");
		});
	};

	/**
	 * 산출물과 파일 전송 (수정)
	 */
	scwin.sendOutputAndFilesForUpdate = function() {
		console.log("sendOutputAndFilesForUpdate() 시작됨");

		var formData = new FormData();

		formData.append("id", dmp_outVoDetail.get("id"));
		formData.append("pjtId", dmp_outVoDetail.get("pjtId"));
		formData.append("name", dmp_outVoDetail.get("name"));
		formData.append("description", dmp_outVoDetail.get("description") || "");
		formData.append("outputType", dmp_outVoDetail.get("outputType") || "DOC");

		// 새로 추가할 파일들
		if (mpd_html5Type && mpd_html5Type.fileArray) {
			var fileList = mpd_html5Type.fileArray;
			console.log("새 파일 리스트", fileList);

			if (fileList && fileList.length > 0) {
				for (var i = 0; i < fileList.length; i++) {
					var realFile = fileList[i].file;
					console.log('새 파일', realFile);
					formData.append("files", realFile);
				}
			}
		}

		fetch("/InsWebApp/OUT001UpdWithFiles.pwkjson", {
			method: "POST",
			body: formData
		})
		.then(function(res) { return res.json(); })
		.then(function(res) {
			var elHeader = res.elHeader;
			if (!elHeader || elHeader.resSuc == false) {
				$c.win.alert(`에러: ${elHeader ? elHeader.resMsg : "알 수 없는 오류"}`);
				return;
			}

			$c.win.alert("수정되었습니다.");
			dlt_upload.removeAll();
			if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
				mpd_html5Type.removeAllFiles();
			}

			// 조회 모드로 전환
			scwin.setFormMode("view");

			// 파일 목록 새로고침
			scwin.loadFileList();

			// 목록 새로고침
			scwin.btn_search_onclick();
		})
		.catch(function(err) {
			console.error("수정 실패", err);
			$c.win.alert("수정 중 오류가 발생했습니다.");
		});
	};

	/**
	 * 산출물 등록 콜백
	 */
	scwin.sbm_insertOutVo_submitdone = function(e) {
		// error 수신시
		var elHeader  = e.responseJSON.elHeader;
		if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}else{
			// 등록되었습니다. msg 출력
			$c.win.alert("등록되었습니다.");
		}

		pop_overlay.hide();
		// 재조회
		scwin.btn_search_onclick();
	};

	/**
	 * 파일 포함 산출물 등록 콜백
	 */
	scwin.sbm_insertOutWithFiles_submitdone = function(e) {
		var elHeader = e.responseJSON.elHeader;
		if (!elHeader || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}

		$c.win.alert("등록되었습니다.");
		dlt_upload.removeAll();
		if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
			mpd_html5Type.removeAllFiles();
		}
		pop_overlay.hide();
		scwin.btn_search_onclick();
	};

	/**
	 * 파일 포함 산출물 수정 콜백
	 */
	scwin.sbm_updateOutWithFiles_submitdone = function(e) {
		var elHeader = e.responseJSON.elHeader;
		if (!elHeader || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}

		$c.win.alert("수정되었습니다.");
		dlt_upload.removeAll();
		if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
			mpd_html5Type.removeAllFiles();
		}

		// 조회 모드로 전환
		scwin.setFormMode("view");

		// 파일 목록 새로고침
		scwin.loadFileList();

		// 목록 새로고침
		scwin.btn_search_onclick();
	};

	/**
	 * 산출물 수정 콜백
	 */
	scwin.sbm_updateOutVo_submitdone = function(e) {
		// error 수신시
		var elHeader  = e.responseJSON.elHeader;
		if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}else{
			// 수정되었습니다. msg 출력
			$c.win.alert("수정되었습니다.");
		}

		// 조회 모드로 전환
		scwin.setFormMode("view");

		// 재조회
		scwin.btn_search_onclick();
	};

	/**
	 * 삭제 버튼 클릭 이벤트
	 */		
	scwin.btn_delete_onclick = function(e) {
		var outputId = dmp_outVoDetail.get("id");

		if (!outputId) {
			$c.win.alert("삭제할 산출물을 선택해주세요.");
			return;
		}

		var promise = $c.win.confirm("산출물을 삭제하시겠습니까?\n관련 파일도 함께 삭제됩니다.");
		promise.then(function(result) {  
			if (result){
				$c.sbm.execute($p, sbm_deleteOutVo);
			}
		});
	};

	/**
	 * 팝업 삭제 버튼 클릭 이벤트
	 */
	scwin.btn_popup_delete_onclick = function(e) {
		scwin.btn_delete_onclick(e);
	};

	/**
	 * 삭제 콜백
	 */
	scwin.sbm_deleteOutVo_submitdone = function(e) {
		// error 수신시
		var elHeader  = e.responseJSON.elHeader;
		if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
			$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
			return false;
		}else{
			// 삭제되었습니다. msg 출력
			$c.win.alert("삭제되었습니다.");
		}

		pop_overlay.hide();
		// 재조회
		scwin.btn_search_onclick();
	};

	/************************** 파일 관련 함수 *************************/

	/**
	 * 파일 업로드 섹션 표시/숨김
	 */
	scwin.showFileUploadSection = function(show) {
		try {
			if (show) {
				grp_fileUploadArea.show();
			} else {
				grp_fileUploadArea.hide();
			}
		} catch(e) {
			console.error("파일 업로드 섹션 표시 오류:", e);
		}
	};

	/**
	 * 파일 선택 완료 콜백
	 */
	scwin.multiUploadSelectDone = function() {
		console.log("파일 선택 완료 콜백 실행");
		var fileInfos = mpd_html5Type.getFileInfos();
		var newFileData = [];

		for (var i = 0; i < fileInfos.length; i++) {
			var file = fileInfos[i];
			newFileData.push({
				originalFileName: file.name,
				fileSize: file.size,
				fileExtension: scwin.getFileExtension(file.name),
				status: "업로드 대기",
				action: "❌"
			});
		}

		dlt_upload.setJSON(newFileData);
		try {
			grd_uploadList.refresh();
		} catch(e) {
			console.log("그리드 새로고침 실패, 무시");
		}

		console.log("업로드 대기 파일 수:", newFileData.length);
	};

	/**
	 * 파일 확장자 추출
	 */
	scwin.getFileExtension = function(fileName) {
		if (!fileName || fileName.indexOf('.') === -1) return '';
		return fileName.split('.').pop().toLowerCase();
	};

	/**
	 * 파일 목록 로드
	 */
	scwin.loadFileList = function() {
		console.log("=== 파일 목록 로드 시작 ===");

		// 현재 선택된 산출물 ID 확인
		var outputId = dmp_outVoDetail.get("id");
		console.log("산출물 ID:", outputId);

		// 산출물 ID가 있는지 확인
		if (!outputId || outputId.trim() === "") {
			console.log("산출물 ID가 없습니다. 파일 목록을 초기화합니다.");
			dlt_attVoList.setJSON([]);
			scwin.hideAllPreviewPanels();
			scwin.showNoPreview();
			return;
		}

		$c.sbm.execute($p, sbm_getOutFileList);
	};

	/**
	 * 파일 목록 조회 성공 콜백
	 */
	scwin.sbm_getOutFileList_submitdone = function(e) {
		console.log("=== 파일 목록 조회 응답 처리 ===");
		console.log("responseJSON:", e.responseJSON);

		var elData = e.responseJSON.elData;
		var elHeader = e.responseJSON.elHeader;

		if (!elHeader || elHeader.resSuc == false) {
			console.error("파일 목록 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
			return false;
		}

		var fileList = elData.attVoList || [];
		console.log("파일 목록 설정 완료:", fileList.length, "개");

		// target에서 이미 dlt_attVoList에 자동 설정됨
		console.log("dlt_attVoList 총 행 수:", dlt_attVoList.getTotalRow());
	};

	/**
	 * 파일 그리드 셀 클릭 이벤트 (미리보기)
	 */
	scwin.grd_fileList_oncellclick = function(row, col, colId) {
		var rowData = dlt_attVoList.getRowJSON(row);

		// 파일명 컬럼 클릭시만 미리보기
		if (colId === "originalFileName") {
			scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
		}
	};

	/**
	 * 파일 그리드 액션 버튼 클릭 이벤트 (다운로드|삭제 버튼)
	 */
	scwin.fileActionClick = function(row, col, colId, targetId) {
		var rowData = dlt_attVoList.getRowJSON(row);
		var fileId = rowData.fileId;
		var fileName = rowData.originalFileName;

		if (targetId.indexOf("download") >= 0 || col === 3) {
			scwin.downloadFile(fileId, fileName);
		} else if (targetId.indexOf("delete") >= 0) {
			scwin.deleteFile(fileId);
		}
	};

	/**
	 * 파일 미리보기 함수
	 */
	scwin.previewFile = function(fileId, fileName, fileExtension) {
		console.log("파일 미리보기:", fileName, fileExtension);

		// 현재 파일 정보 저장
		dmp_currentFile.set("fileId", fileId);
		dmp_currentFile.set("originalFileName", fileName);
		dmp_currentFile.set("fileExtension", fileExtension);

		// 모든 미리보기 영역 숨기기
		scwin.hideAllPreviewPanels();

		// 파일 확장자에 따른 미리보기 처리
		var ext = fileExtension ? fileExtension.toLowerCase() : "";

		if (scwin.isImageFile(ext)) {
			scwin.showImagePreview(fileId, fileName);
		} else if (scwin.isTextFile(ext)) {
			scwin.showTextPreview(fileId, fileName);
		} else if (scwin.isDocumentFile(ext)) {
			scwin.showDocumentPreview(fileId, fileName, ext);
		} else {
			scwin.showUnsupportedPreview(fileName);
		}
	};

	/**
	 * 파일 타입 체크 함수들
	 */
	scwin.isImageFile = function(ext) {
		var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'];
		return imageExts.indexOf(ext) !== -1;
	};

	scwin.isTextFile = function(ext) {
		var textExts = ['txt', 'log', 'csv', 'json', 'xml', 'html', 'css', 'js', 'java', 'sql', 'properties'];
		return textExts.indexOf(ext) !== -1;
	};

	scwin.isDocumentFile = function(ext) {
		var docExts = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp'];
		return docExts.indexOf(ext) !== -1;
	};

	/**
	 * 모든 미리보기 패널 숨기기
	 */
	scwin.hideAllPreviewPanels = function() {
		try {
			grp_noPreview.hide();
			grp_imagePreview.hide();
			grp_textPreview.hide();
			grp_documentPreview.hide();
		} catch(e) {
			var panels = ['grp_noPreview', 'grp_imagePreview', 'grp_textPreview', 'grp_documentPreview'];
			panels.forEach(function(panelId) {
				var element = document.getElementById(panelId);
				if (element) {
					element.style.display = 'none';
				}
			});
		}
	};

	/**
	 * 기본 미리보기 표시
	 */
	scwin.showNoPreview = function() {
		try {
			grp_noPreview.show();
		} catch(e) {
			var element = document.getElementById('grp_noPreview');
			if (element) element.style.display = 'block';
		}
	};

	/**
	 * 이미지 미리보기 표시
	 */
	scwin.showImagePreview = function(fileId, fileName) {
		var imageUrl = "/InsWebApp/ImagePreview.pwkjson?fileId=" + fileId;

		try {
			txt_previewFileName.setValue(fileName);
			grp_imagePreview.show();

			setTimeout(function() {
				var imgElement = document.getElementById("img_preview");
				if (imgElement) {
					imgElement.src = imageUrl;

					// 썸네일 스타일 적용
					imgElement.style.width = "150px";
					imgElement.style.height = "150px";
					imgElement.style.objectFit = "cover";
					imgElement.style.border = "1px solid #ddd";
					imgElement.style.background = "white";
					imgElement.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
					imgElement.style.borderRadius = "4px";

					imgElement.onerror = function() {
						console.error("이미지 로드 실패:", imageUrl);
						scwin.showUnsupportedPreview(fileName, "이미지를 로드할 수 없습니다.");
					};
					imgElement.onload = function() {
						console.log("이미지 로드 성공:", fileName);
					};
				}
			}, 100);
		} catch(e) {
			console.error("이미지 미리보기 오류:", e);
			scwin.showUnsupportedPreview(fileName);
		}
	};

	/**
	 * 텍스트 파일 미리보기 표시
	 */
	scwin.showTextPreview = function(fileId, fileName) {
		try {
			txt_textFileName.setValue(fileName);
			grp_textPreview.show();

			// AttController의 FilePreview 사용
			fetch("/InsWebApp/FilePreview.pwkjson?fileId=" + fileId)
				.then(function(response) { 
					return response.json(); 
				})
				.then(function(data) {
					if (data.success && data.content) {
						// Base64 디코딩
						var decodedContent = atob(data.content);
						if (decodedContent.length > 5000) {
							decodedContent = decodedContent.substring(0, 5000) + "\n\n... (파일 내용이 길어서 일부만 표시됩니다)";
						}
						txt_textContent.setValue(decodedContent);
					} else {
						txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다: " + (data.message || "알 수 없는 오류"));
					}
				})
				.catch(function(error) {
					console.error("텍스트 파일 로드 실패:", error);
					txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다.");
				});
		} catch(e) {
			console.error("텍스트 미리보기 오류:", e);
			scwin.showUnsupportedPreview(fileName);
		}
	};

	/**
	 * 문서 파일 미리보기 표시
	 */
	scwin.showDocumentPreview = function(fileId, fileName, ext) {
		try {
			txt_documentFileName.setValue(fileName);

			var fileInfo = "";
			switch(ext) {
				case 'pdf':
					fileInfo = "PDF 문서 파일입니다.";
					break;
				case 'doc':
				case 'docx':
					fileInfo = "Microsoft Word 문서입니다.";
					break;
				case 'xls':
				case 'xlsx':
					fileInfo = "Microsoft Excel 스프레드시트입니다.";
					break;
				case 'ppt':
				case 'pptx':
					fileInfo = "Microsoft PowerPoint 프레젠테이션입니다.";
					break;
				case 'hwp':
					fileInfo = "한글 문서 파일입니다.";
					break;
				default:
					fileInfo = "문서 파일입니다.";
			}

			txt_documentInfo.setValue(fileInfo);
			grp_documentPreview.show();
		} catch(e) {
			console.error("문서 미리보기 오류:", e);
			scwin.showUnsupportedPreview(fileName);
		}
	};

	/**
	 * 지원하지 않는 파일 미리보기
	 */
	scwin.showUnsupportedPreview = function(fileName, message) {
		scwin.hideAllPreviewPanels();
		scwin.showNoPreview();
	};

	/**
	 * 현재 미리보기 중인 파일 다운로드
	 */
	scwin.downloadCurrentFile = function() {
		var fileId = dmp_currentFile.get("fileId");
		var fileName = dmp_currentFile.get("originalFileName");

		if (fileId && fileName) {
			scwin.downloadFile(fileId, fileName);
		} else {
			alert("다운로드할 파일 정보가 없습니다.");
		}
	};

	/**
	 * 파일 다운로드
	 */
	scwin.downloadFile = function(fileId, fileName) {
		if (!fileId || !fileName) {
			alert("다운로드할 파일 정보가 없습니다.");
			return;
		}

		console.log("파일 다운로드 시작:", fileName);

		try {
			// AttController의 FileDownload 사용
			var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

			var iframe = document.createElement('iframe');
			iframe.style.display = 'none';
			iframe.src = downloadUrl;
			document.body.appendChild(iframe);

			setTimeout(function() {
				if (iframe.parentNode) {
					document.body.removeChild(iframe);
				}
			}, 2000);

		} catch (error) {
			console.error("파일 다운로드 실패:", error);
			alert("파일 다운로드 중 오류가 발생했습니다.");
		}
	};

	/**
	 * 파일 삭제
	 */
	scwin.deleteFile = function(fileId) {
		if (!fileId) {
			alert("삭제할 파일을 선택해주세요.");
			return;
		}

		var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
		promise.then(function(result) {
			if (result) {
				// FormData 방식으로 전송
				var formData = new FormData();
				formData.append("fileId", fileId);

				fetch("/InsWebApp/OUT001FileDelete.pwkjson", {
					method: "POST",
					body: formData
				})
				.then(function(response) {
					return response.json();
				})
				.then(function(data) {
					var elHeader = data.elHeader;
					if (elHeader && elHeader.resSuc === true) {
						alert("파일이 삭제되었습니다.");

						// 현재 미리보기 중인 파일이 삭제된 경우 미리보기 초기화
						if (dmp_currentFile.get("fileId") === fileId) {
							scwin.hideAllPreviewPanels();
							scwin.showNoPreview();
							dmp_currentFile.setEmptyValue();
						}

						scwin.loadFileList();
					} else {
						alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
					}
				})
				.catch(function(error) {
					console.error("파일 삭제 실패:", error);
					alert("파일 삭제 중 오류가 발생했습니다.");
				});
			}
		});
	};

	/**
	 * 업로드 파일 삭제
	 */
	scwin.removeUploadFile = function(row, col, colId, targetId) {
		console.log("업로드 파일 삭제:", row);

		try {
			// 그리드에서 해당 행 삭제
			dlt_upload.removeRow(row);

			// multiupload 컴포넌트에서도 해당 파일 제거
			if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
				mpd_html5Type.removeFileByIndex(row);
			} else if (mpd_html5Type && mpd_html5Type.fileArray) {
				// 직접 fileArray에서 제거
				mpd_html5Type.fileArray.splice(row, 1);
			}

			console.log("파일 삭제 완료, 남은 파일 수:", dlt_upload.getTotalRow());

			// 그리드 새로고침
			try {
				grd_uploadList.refresh();
			} catch(e) {
				console.log("그리드 새로고침 실패, 무시");
			}

		} catch(error) {
			console.error("파일 삭제 중 오류:", error);
			alert("파일 삭제 중 오류가 발생했습니다.");
		}
	};

	/**
	 * 파일 업로드 초기화
	 */
	scwin.btn_InitMultiupload_onclick = function(e) {
		console.log("파일 업로드 초기화");

		// 그리드 데이터 삭제
		dlt_upload.removeAll();

		// multiupload 컴포넌트 초기화
		if (mpd_html5Type) {
			if (mpd_html5Type.clear) {
				mpd_html5Type.clear();
			} else if (mpd_html5Type.removeAllFiles) {
				mpd_html5Type.removeAllFiles();
			} else if (mpd_html5Type.fileArray) {
				mpd_html5Type.fileArray = [];
			}
		}

		console.log("파일 업로드 초기화 완료");
	};
